float lerp(float factor, float a, float b) {
    return a + (b - a) * factor;
}

// https://gist.github.com/983/e170a24ae8eba2cd174f
vec3 hsv2rgb(vec3 c)
{
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // VALUES YOU CAN PLAY AROUND WITH
    vec2 pos = vec2(-1.0121f, 0.2556f);
    float zoomspeed = 3.0f;
    float iter = 400.0f;

    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    float real = uv[0];
    float imag = uv[1];

    float col = 0.0f;

    // scalor
    float zoom = 1.0f;
    if(iTime >= 1.0f) {
           zoom = pow(iTime, zoomspeed);
    }

    real = lerp(uv[0], pos[0]-(2.2f/zoom), pos[0]+(1.0f/zoom));
    imag = lerp(uv[1], pos[1]-(1.0f/zoom), pos[1]+(1.0f/zoom));

    float creal = real;
    float cimag = imag;

    for(float i = 0.0f; i < iter; i++){
        float realtemp = real;
        real = (real*real)-(imag*imag)+creal;
        imag = 2.0f*(realtemp*imag)+cimag;
        if(sqrt((real*real) + (imag*imag)) > 4.0f){
            col = i/iter;
        }
    }
    // Output to screen
    vec3 color = vec3(0.0f, 0.0f, 0.0f);
    if(col != 0.0f) {
        color = hsv2rgb(vec3(col*2.0f, 1.0f, 1.0f));
    }
    fragColor = vec4(color, 1.0);
}
